// Table sounds and music. Recorded effects live in src/audio (generated by
// scripts/make-sfx.ps1) and are decoded on the first pointer gesture, so
// browsers' autoplay rules are respected. Any effect whose file is missing
// falls back to a tiny built-in synth, so the game is never silent and never
// depends on the files. Music is any src/audio/music-*.mp3, looped quietly.

const FILES = import.meta.glob ? import.meta.glob("../audio/*.{mp3,ogg,wav}", { eager: true, query: "?url", import: "default" }) : {};
const URLS = {};
Object.entries(FILES).forEach(([path, url]) => { URLS[path.split("/").pop().replace(/\.[a-z0-9]+$/, "")] = url; });
const MUSIC_URL = Object.entries(URLS).find(([name]) => name.startsWith("music"))?.[1] || null;

let ctx = null;
let noiseBuffer = null;
let recent = [];
let loading = false;
// name -> { buffer, offset } where offset skips any silence before the sound.
const samples = new Map();
let music = null;

const MUTE_KEY = "rokumon-pool:muted";
const MUSIC_KEY = "rokumon-pool:music";
let muted = false;
let musicOn = true;
try { muted = localStorage.getItem(MUTE_KEY) === "1"; } catch { muted = false; }
try { musicOn = localStorage.getItem(MUSIC_KEY) !== "0"; } catch { musicOn = true; }

function ensure() {
  if (!ctx) {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    ctx = new AC();
  }
  if (ctx.state === "suspended") ctx.resume().catch(() => {});
  return ctx;
}

// Generated effects often start with a few milliseconds of silence, which
// would make a ball click land late. Find where the sound really begins.
function leadIn(buffer) {
  const data = buffer.getChannelData(0);
  const limit = Math.min(data.length, Math.floor(buffer.sampleRate * 0.4));
  for (let i = 0; i < limit; i += 1) {
    if (Math.abs(data[i]) > 0.02) return Math.max(0, i / buffer.sampleRate - 0.003);
  }
  return 0;
}

function loadSamples(c) {
  if (loading) return;
  loading = true;
  Object.entries(URLS).forEach(([name, url]) => {
    if (name.startsWith("music")) return;
    fetch(url)
      .then((response) => response.arrayBuffer())
      .then((bytes) => c.decodeAudioData(bytes))
      .then((buffer) => samples.set(name, { buffer, offset: leadIn(buffer) }))
      .catch(() => { /* the synth covers a file that will not load */ });
  });
}

function throttled() {
  const now = performance.now();
  recent = recent.filter((t) => now - t < 60);
  if (recent.length >= 6) return true;
  recent.push(now);
  return false;
}

// Plays a recorded effect. Returns false if it is not available, so the
// caller can fall back to the synth.
function sample(names, { gain = 1, rate = 1, limit = true } = {}) {
  const c = ensure();
  if (!c || muted) return true;
  const have = names.filter((n) => samples.has(n));
  if (!have.length) return false;
  if (limit && throttled()) return true;
  const { buffer, offset } = samples.get(have[Math.floor(Math.random() * have.length)]);
  const src = c.createBufferSource();
  src.buffer = buffer;
  src.playbackRate.value = rate;
  const env = c.createGain();
  env.gain.value = gain;
  src.connect(env).connect(c.destination);
  src.start(c.currentTime, offset);
  return true;
}

function getNoise(c) {
  if (noiseBuffer) return noiseBuffer;
  const length = Math.floor(c.sampleRate * 0.2);
  noiseBuffer = c.createBuffer(1, length, c.sampleRate);
  const data = noiseBuffer.getChannelData(0);
  for (let i = 0; i < length; i += 1) data[i] = Math.random() * 2 - 1;
  return noiseBuffer;
}

function burst({ duration, gain, cutoff, q = 1 }) {
  const c = ensure();
  if (!c || muted || throttled()) return;
  const src = c.createBufferSource();
  src.buffer = getNoise(c);
  const filter = c.createBiquadFilter();
  filter.type = "bandpass";
  filter.frequency.value = cutoff;
  filter.Q.value = q;
  const env = c.createGain();
  const t = c.currentTime;
  env.gain.setValueAtTime(gain, t);
  env.gain.exponentialRampToValueAtTime(0.0005, t + duration);
  src.connect(filter).connect(env).connect(c.destination);
  src.start(t);
  src.stop(t + duration + 0.02);
}

function tone({ from, to, duration, gain, type = "sine", delay = 0 }) {
  const c = ensure();
  if (!c || muted) return;
  const osc = c.createOscillator();
  osc.type = type;
  const env = c.createGain();
  const t = c.currentTime + delay;
  osc.frequency.setValueAtTime(from, t);
  osc.frequency.exponentialRampToValueAtTime(to, t + duration);
  env.gain.setValueAtTime(gain, t);
  env.gain.exponentialRampToValueAtTime(0.0005, t + duration);
  osc.connect(env).connect(c.destination);
  osc.start(t);
  osc.stop(t + duration + 0.02);
}

const clamp01 = (v) => Math.max(0, Math.min(1, v));
const vary = () => 0.95 + Math.random() * 0.1;

function syncMusic() {
  if (!MUSIC_URL) return;
  const want = musicOn && !muted;
  if (want && !music) {
    music = new Audio(MUSIC_URL);
    music.loop = true;
    music.volume = 0.32;
  }
  if (!music) return;
  if (want) music.play().catch(() => { /* waits for the next gesture */ });
  else music.pause();
}

export const audio = {
  // Call from a pointer or key gesture: starts the audio context, loads the
  // recorded effects and starts the music if it is switched on.
  unlock() {
    const c = ensure();
    if (c) loadSamples(c);
    syncMusic();
  },
  get muted() { return muted; },
  setMuted(value) {
    muted = Boolean(value);
    try { localStorage.setItem(MUTE_KEY, muted ? "1" : "0"); } catch { /* per-viewer convenience only */ }
    syncMusic();
    return muted;
  },
  toggleMuted() { return audio.setMuted(!muted); },
  get hasMusic() { return Boolean(MUSIC_URL); },
  get musicOn() { return musicOn; },
  toggleMusic() {
    musicOn = !musicOn;
    try { localStorage.setItem(MUSIC_KEY, musicOn ? "1" : "0"); } catch { /* per-viewer convenience only */ }
    syncMusic();
    return musicOn;
  },
  // The game pauses when the tab is hidden; the music should too.
  pauseMusic() { if (music) music.pause(); },
  resumeMusic() { syncMusic(); },

  // Ball on ball: three recorded clicks from gentle to hard, scaled by
  // impact speed and pitched slightly differently each time.
  click(intensity) {
    const v = clamp01(intensity);
    if (v < 0.04) return;
    const names = v > 0.5 ? ["clack-2", "clack-1"] : v > 0.18 ? ["clack-1"] : ["clack-3"];
    if (sample(names, { gain: 0.25 + v * 0.75, rate: vary() * (1.06 - v * 0.1) })) return;
    burst({ duration: 0.035 + v * 0.03, gain: 0.05 + v * 0.35, cutoff: 2600 + v * 3000, q: 1.2 });
  },
  // Ball on cushion: a duller thud.
  thud(intensity) {
    const v = clamp01(intensity);
    if (v < 0.06) return;
    if (sample(["cushion-1", "cushion-2"], { gain: 0.2 + v * 0.7, rate: vary() })) return;
    burst({ duration: 0.05 + v * 0.04, gain: 0.03 + v * 0.18, cutoff: 380 + v * 300, q: 0.8 });
  },
  // Cue strike: soft or hard, scaled by power.
  strike(power) {
    const v = clamp01(power);
    if (sample([v > 0.6 ? "cue-hard" : "cue-soft"], { gain: 0.45 + v * 0.55, rate: vary(), limit: false })) return;
    burst({ duration: 0.05, gain: 0.08 + v * 0.25, cutoff: 1400 + v * 800, q: 0.9 });
  },
  // Ball dropping into a pocket.
  pocket() {
    if (sample(["pocket-1", "pocket-2"], { gain: 0.8, rate: vary(), limit: false })) return;
    tone({ from: 320, to: 90, duration: 0.22, gain: 0.18, type: "triangle" });
    burst({ duration: 0.16, gain: 0.12, cutoff: 900, q: 0.6 });
  },
  rack() { sample(["rack"], { gain: 0.6, limit: false }); },
  ui() {
    if (sample(["ui-click"], { gain: 0.5, limit: false })) return;
    burst({ duration: 0.02, gain: 0.08, cutoff: 1800, q: 1.5 });
  },
  foul() {
    if (sample(["foul"], { gain: 0.8, limit: false })) return;
    tone({ from: 190, to: 150, duration: 0.14, gain: 0.2, type: "square" });
    tone({ from: 150, to: 110, duration: 0.2, gain: 0.2, type: "square", delay: 0.17 });
  },
  win() {
    if (sample(["win"], { gain: 0.8, limit: false })) return;
    [392, 494, 587, 784].forEach((f, i) => tone({ from: f, to: f, duration: 0.3, gain: 0.14, type: "triangle", delay: i * 0.12 }));
  },
  lose() {
    if (sample(["lose"], { gain: 0.8, limit: false })) return;
    [392, 330, 262].forEach((f, i) => tone({ from: f, to: f * 0.97, duration: 0.35, gain: 0.14, type: "triangle", delay: i * 0.18 }));
  },
  trophy() {
    if (sample(["trophy"], { gain: 0.8, limit: false })) return;
    [784, 988, 1175].forEach((f, i) => tone({ from: f, to: f, duration: 0.4, gain: 0.1, delay: i * 0.1 }));
  },
};
